svg.script:
(function () {
  const svg = document.getElementById('magic-square-order5');
  const cells = Array.from(svg.querySelectorAll('.hit-cell'));
  const axes = {
    row: svg.getElementById('axis-row'),
    col: svg.getElementById('axis-col'),
    diag1: svg.getElementById('axis-diag1'),
    diag2: svg.getElementById('axis-diag2')
  };
  const gridLeft = 48;
  const gridRight = 568;
  const gridTop = 48;
  const gridBottom = 568;
  const cellSize = 104;
  let pinned = null;
  let active = null;

  function clearVisuals() {
    svg.querySelectorAll('.cell-wash.on').forEach(el => el.classList.remove('on'));
    svg.querySelectorAll('.cell-outline.selected').forEach(el => el.classList.remove('selected'));
    Object.values(axes).forEach(el => el.classList.remove('on'));
  }

  function activateCell(el) {
    if (!el) {
      active = null;
      clearVisuals();
      return;
    }
    active = el;
    clearVisuals();
    const id = el.dataset.id;
    const row = Number(el.dataset.row);
    const col = Number(el.dataset.col);
    const cx = Number(el.dataset.x);
    const cy = Number(el.dataset.y);

    // Outline selected cell
    const outline = svg.getElementById(id + '_outline');
    if (outline) outline.classList.add('selected');

    // Highlight row cells
    for (let c = 0; c < 5; c++) {
      const node = svg.getElementById(`c_${row}_${c}_row`);
      if (node) node.classList.add('on');
    }
    // Highlight column cells
    for (let r = 0; r < 5; r++) {
      const node = svg.getElementById(`c_${r}_${col}_col`);
      if (node) node.classList.add('on');
    }
    // Main diagonal
    const onDiag1 = row === col;
    if (onDiag1) {
      for (let i = 0; i < 5; i++) {
        const node = svg.getElementById(`c_${i}_${i}_diag1`);
        if (node) node.classList.add('on');
      }
    }
    // Anti-diagonal
    const onDiag2 = (row + col) === 4;
    if (onDiag2) {
      for (let i = 0; i < 5; i++) {
        const node = svg.getElementById(`c_${i}_${4 - i}_diag2`);
        if (node) node.classList.add('on');
      }
    }

    // Strike-through axes
    axes.row.setAttribute('x1', gridLeft);
    axes.row.setAttribute('y1', cy);
    axes.row.setAttribute('x2', gridRight);
    axes.row.setAttribute('y2', cy);
    axes.row.classList.add('on');

    axes.col.setAttribute('x1', cx);
    axes.col.setAttribute('y1', gridTop);
    axes.col.setAttribute('x2', cx);
    axes.col.setAttribute('y2', gridBottom);
    axes.col.classList.add('on');

    if (onDiag1) axes.diag1.classList.add('on');
    if (onDiag2) axes.diag2.classList.add('on');
  }

  function showFromHover(el) {
    if (pinned) return;
    activateCell(el);
  }

  function clearHover() {
    if (pinned) {
      activateCell(pinned);
    } else {
      activateCell(null);
    }
  }

  function togglePin(el) {
    if (pinned === el) {
      pinned = null;
      activateCell(null);
      return;
    }
    pinned = el;
    activateCell(el);
  }

  cells.forEach(el => {
    el.addEventListener('mouseenter', () => showFromHover(el));
    el.addEventListener('mouseleave', clearHover);
    el.addEventListener('focus', () => showFromHover(el));
    el.addEventListener('blur', clearHover);
    el.addEventListener('click', (ev) => {
      ev.preventDefault();
      togglePin(el);
    });
    el.addEventListener('keydown', (ev) => {
      if (ev.key === 'Enter' || ev.key === ' ') {
        ev.preventDefault();
        togglePin(el);
      } else if (ev.key === 'Escape') {
        ev.preventDefault();
        pinned = null;
        activateCell(null);
      }
    });
  });

  svg.addEventListener('mouseleave', () => {
    if (!pinned) activateCell(null);
  });
  svg.addEventListener('touchstart', () => {}, { passive: true });
  document.addEventListener('keydown', (ev) => {
    if (document.activeElement && svg.contains(document.activeElement)) {
      if (ev.key === 'Escape') {
        pinned = null;
        activateCell(null);
      }
    }
  });
})();
